/// <summary>
/// <c>METPrintdestinationService</c> service class use to print the report
/// </summary>
public class METPrintDestinationService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// service class process method
/// </summary>
/// <param name = "_contract">METPrintDestinationContract</param>
/// <param name = "_srsPrintDestinationSettings">SRSPrintDestinationSettings</param>
public void process(METPrintDestinationContract _contract, SRSPrintDestinationSettings _srsPrintDestinationSettings)
{
    if (this.isExecutingInBatch())
    {
        METPrintDestinationService::loopRecords(_contract, _srsPrintDestinationSettings);
    }
}

/// <summary>
/// loop record method
/// </summary>
/// <param name = "_contract">METPrintDestinationContract</param>
/// <param name = "_srsPrintDestinationSettings">SRSPrintDestinationSettings</param>
public static void loopRecords(METPrintDestinationContract _contract, SRSPrintDestinationSettings _srsPrintDestinationSettings)
{
    System.     Exception       ex;
    container   conRecord = _contract.parmRecordCon();

    for(int conCounter = 1; conlen(conRecord) >= conCounter; conCounter++)
    {
        try
        {
            //// generate code
            if(_contract.parmMenuItemName() == menuitemActionStr(METSOShipment))
            {
                METPrintDestinationService::generateSOShipment(_contract, _srsPrintDestinationSettings, conPeek(conRecord, conCounter));
            }
            else
            {
                METPrintDestinationService::generateReport(_contract, _srsPrintDestinationSettings);// it may differ based on the requirement of the report
            }
        }
        catch
        {
            ex = CLRInterop::getLastException().GetBaseException();

            continue;
        }
    }
}

/// <summary>
/// generateReport method
/// </summary>
/// <param name = "_contract">METPrintDestinationContract</param>
/// <param name = "_srsPrintDestinationSettings">SRSPrintDestinationSettings</param>
public static void generateReport(METPrintDestinationContract _contract, SRSPrintDestinationSettings _srsPrintDestinationSettings)
{
    //SRSPrintDestinationSettings     settings;
    //Filename                        fileName    = strFmt("TestReport");
    SrsReportRunController          controller  = new SrsReportRunController();
    METPrintDestinationContract     contract    = new METPrintDestinationContract();

    controller.parmArgs(new Args());
    controller.parmReportName(METPrintDestinationService::getReportName(_contract.parmMenuItemName()));// report name to be assigned based on the caller menuitem
    controller.parmShowDialog(false);
    controller.parmLoadFromSysLastValue(false);
    controller.parmReportContract().parmRdpContract(contract);

    if(_contract.parmUsePrintMgmt() == NoYes::No)
    {
        controller.parmReportContract().parmPrintSettings(_srsPrintDestinationSettings);
        // --- or----
        //settings = controller.parmReportContract().parmPrintSettings();
        //settings.printMediumType(_sRSPrintDestinationSettings.printMediumType());
        //settings.fileName(_sRSPrintDestinationSettings.fileName());
        //settings.fileFormat(_sRSPrintDestinationSettings.fileFormat());
        //settings.overwriteFile(true);
    }

    controller.startOperation();
}

/// <summary>
/// generateSOShipment
/// </summary>
/// <param name = "_contract">METPrintDestinationContract</param>
/// <param name = "_srsPrintDestinationSettings">SRSPrintDestinationSettings</param>
/// <param name = "_recId">RefRecId</param>
public static void generateSOShipment(METPrintDestinationContract _contract, SRSPrintDestinationSettings _srsPrintDestinationSettings, RefRecId _recId)
{
    SalesPackingSlipJournalPrint        salesPackingSlipJournalPrint;
    SRSPrintDestinationSettings         srsPrintDestinationSettings;
    boolean                             hasRecord = false;
    CustPackingSlipJour                 packingSlipJourLoc;
    CustPackingSlipJour                 packingSlipJour;

    select firstonly packingSlipJourLoc
        where packingSlipJourLoc.RecId == _recId;
    If(packingSlipJourLoc)
    {
        Set set = new Set(Types::Record);

        while select packingSlipJour
                where packingSlipJour.METShipmentId == packingSlipJourLoc.METShipmentId
        {
            // Add record
            set.add(packingSlipJour);
            hasRecord = true;
        }

        if(hasRecord)
        {
            // Set printer settings
            srsPrintDestinationSettings = new SRSPrintDestinationSettings();
            //srsPrintDestinationSettings.fileFormat(SRSReportFileFormat::Screen);
            // Initalize
            salesPackingSlipJournalPrint = SalesPackingSlipJournalPrint::construct();
            salesPackingSlipJournalPrint.parmPrintFormletter(NoYes::Yes);
            salesPackingSlipJournalPrint.parmUsePrintManagement(_contract.parmUsePrintMgmt());
            salesPackingSlipJournalPrint.parmPrinterSettingsFormLetter(_contract.parmUsePrintMgmt() == NoYes::Yes ? srsPrintDestinationSettings.pack() : _srsPrintDestinationSettings.pack());

            // Print
            salesPackingSlipJournalPrint.printJournal(set);
        }
    }
}

/// <summary>
/// method to fetch the report name
/// </summary>
/// <param name = "_menuItemName">str</param>
/// <returns>str</returns>
public static str getReportName(str _menuItemName)
{   
    ReportName  reportName;
    switch(_menuItemName)
    {
        case '' : // name of the menuitem
            reportName = ''; // Report name should be assigned based on the menuitem
            break;
    }

    return reportName;
}
